<aside id="accessibilityPanel" class="accessibility-panel" aria-labelledby="accessibilityTitle" hidden>
<div class="accessibility-heading"><span class="a11y-heading-icon"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="4" r="2"/><path d="M4 8h16m-8 0v6m0 0-5 7m5-7 5 7"/></svg></span><h2 id="accessibilityTitle">Accesibilidad</h2><span id="accessibilityReadingState" class="a11y-reading-state" data-no-translate>Lectura: inactiva</span><button type="button" id="accessibilityClose" aria-label="Cerrar accesibilidad">×</button></div>
<fieldset><legend><span class="a11y-section-icon" aria-hidden="true">Aᴬ</span><span>Tamaño del texto</span></legend><div class="accessibility-text-controls"><button type="button" id="accessibilitySmaller" aria-label="Disminuir tamaño del texto">A−</button><output id="accessibilityTextSize" aria-live="polite">100 %</output><button type="button" id="accessibilityLarger" aria-label="Aumentar tamaño del texto">A+</button></div></fieldset>
<fieldset><legend><span class="a11y-section-icon" aria-hidden="true"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M12 3a9 9 0 1 0 0 18h2a2 2 0 0 0 1-3.7 1.6 1.6 0 0 1 .8-3H18a3 3 0 0 0 3-3 9 9 0 0 0-9-8Z"/><path d="M7 10h.01M10 6h.01M15 6h.01M18 10h.01"/></svg></span><span>Tema de color</span></legend><div class="accessibility-themes"><button type="button" data-accessibility-theme="light" class="accessibility-swatch swatch-light" aria-label="Tema claro" title="Tema claro" aria-pressed="false"><span class="a11y-color-sample">A</span><small>Estándar</small></button><button type="button" data-accessibility-theme="sepia" class="accessibility-swatch swatch-sepia" aria-label="Tema sepia" title="Tema sepia" aria-pressed="false"><span class="a11y-color-sample">A</span><small>Cálido</small></button><button type="button" data-accessibility-theme="dark" class="accessibility-swatch swatch-dark" aria-label="Tema oscuro" title="Tema oscuro" aria-pressed="false"><span class="a11y-color-sample">A</span><small>Azul oscuro</small></button><button type="button" data-accessibility-theme="contrast" class="accessibility-swatch swatch-contrast" aria-label="Alto contraste blanco" title="Alto contraste blanco" aria-pressed="false"><span class="a11y-color-sample">A</span><small>Alto contraste</small></button><button type="button" data-accessibility-theme="yellow" class="accessibility-swatch swatch-yellow" aria-label="Alto contraste amarillo" title="Alto contraste amarillo" aria-pressed="false"><span class="a11y-color-sample">A</span><small>Invertido</small></button></div></fieldset>
<fieldset><legend><span class="a11y-section-icon" aria-hidden="true"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m11 5-6 4H2v6h3l6 4V5Zm4 3a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/></svg></span><span>Leer en voz alta</span></legend><div class="accessibility-reading">
<button type="button" id="accessibilitySelection"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="m5 3 14 9-7 1-3 7-4-17Z"/></svg><span>Selección</span></button>
<button type="button" id="accessibilityPage"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M6 2h8l4 4v16H6V2Zm8 0v5h5"/></svg><span>Página</span></button>
<button type="button" id="accessibilityPause" disabled><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M9 5v14m6-14v14"/></svg><span id="accessibilityPauseLabel">Pausar</span></button>
<button type="button" id="accessibilityStop"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="5" y="5" width="14" height="14" rx="1"/></svg><span>Detener</span></button></div></fieldset>
<div class="a11y-setting"><label for="accessibilityVoice"><span class="a11y-section-icon" aria-hidden="true"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/></svg></span><span>Voz</span></label><select id="accessibilityVoice"></select></div>
<div class="a11y-setting"><label for="accessibilityRate"><span class="a11y-section-icon" aria-hidden="true"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M4 19a10 10 0 1 1 16 0M12 12l4-5M5 12h1m12 0h1M8 5l1 1"/></svg></span><span>Velocidad de lectura</span></label><div class="accessibility-rate"><input id="accessibilityRate" type="range" min="0.5" max="2" step="0.1" value="1"><output id="accessibilityRateValue" for="accessibilityRate">1.0×</output></div></div>
<p id="accessibilityStatus" class="accessibility-status" role="status" aria-live="polite"></p>
<button type="button" id="accessibilityReset" class="accessibility-reset"><svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"><path d="M3 10a9 9 0 1 1 1 8M3 3v7h7"/></svg><span>Restablecer ajustes</span></button>
</aside>

